const initialLanguage = resolveDesktopLanguage(navigator.language)

void i18n.use(initReactI18next).init({
  resources: withSourceRepairMessages(resources),
  lng: initialLanguage,
  fallbackLng: 'en',
  interpolation: { escapeValue: false }
})

export default i18n
